function renderChildren(n){return n.map(n=>`\n        <div style="display:flex; gap:0.5rem; align-items:center; background: #f9fafb; padding: 0.5rem; border-radius: 6px;">\n            <span style="font-weight:bold; min-width: 80px;">${n.name}</span>\n            <span style="font-size:0.8rem; color:#666">Bal: ${n.balance}</span>\n            <div style="flex:1; display:flex; gap:0.3rem;">\n                <input type="text" readonly value="${window.location.origin}/login-child/${n.token}" style="flex:1; font-size:0.8rem; border:1px solid #ddd; padding:2px 4px; border-radius:4px;">\n                <button class="view-btn" onclick="copyMagicLink('${n.token}')">Copy</button>\n                <button class="block-btn" style="background:#f59e0b; padding:2px 6px;" onclick="regenerateToken(null, ${n.id})">Refresh</button>\n            </div>\n        </div>\n    `).join("")}function renderTasks(n){return n.map(n=>`\n        <tr>\n            <td>${n.name}</td>\n            <td>${n.coins} 🪙</td>\n        </tr>\n    `).join("")}function renderShopItems(n){return n.map(n=>{const t=n.frequency?`<br><small>${n.frequency.limit}/${n.frequency.period}</small>`:"",e=n.money_limit?`<br><small>Limit: ${n.money_limit}🪙</small>`:"";return`\n            <tr>\n                <td>${n.name}${t}${e}</td>\n                <td>${n.price} 🪙</td>\n            </tr>\n        `}).join("")}function renderRecentHistory(n){return 0===n.length?"<p>Нет записей</p>":`\n        <table>\n            <tbody>\n                ${n.slice(-10).reverse().map(n=>`\n                    <tr>\n                        <td>${new Date(n.timestamp).toLocaleString("ru-RU")}</td>\n                        <td>${n.action}</td>\n                    </tr>\n                `).join("")}\n            </tbody>\n        </table>\n    `}function renderFamilyGrid(n){const{created_at:t,email:e,monthly_limit:i,children:d}=n.familyInfo,{balance:r}=n.data;return`\n        <div class="detail-grid">\n            <div class="detail-item"><strong>ID семьи</strong><div>#${n.familyId}</div></div>\n            <div class="detail-item"><strong>Дата создания</strong><div>${new Date(t).toLocaleString("ru-RU")}</div></div>\n            <div class="detail-item"><strong>Email</strong><div>${e||"-"}</div></div>\n            <div class="detail-item"><strong>Баланс</strong><div>${r} 🪙</div></div>\n            <div class="detail-item"><strong>Лимит (мес)</strong><div>${i||1e4}</div></div>\n            <div class="detail-item" style="grid-column: span 2">\n                <strong>Дети (${d.length})</strong>\n                <div style="margin-top:0.5rem; display:flex; flex-direction:column; gap:0.5rem;">\n                    ${renderChildren(d)}\n                </div>\n            </div>\n        </div>\n    `}function renderDetailsSection(n,t,e){return`\n        <h3>${n} (${t.length})</h3>\n        <table>\n            <thead><tr><th>Название</th><th>${n.includes("Задания")?"Награда":"Цена"}</th></tr></thead>\n            <tbody>${e(t)}</tbody>\n        </table>\n    `}export function renderFamilyDetails(n){const t=document.getElementById("modal-title"),e=document.getElementById("modal-body");t.textContent=n.familyInfo.email||`Family ${n.familyId}`,e.innerHTML=`\n        ${renderFamilyGrid(n)}\n        ${renderDetailsSection("📋 Задания",n.data.tasks,renderTasks)}\n        ${renderDetailsSection("🏪 Магазин",n.data.shop,renderShopItems)}\n        <h3>📜 История (${n.data.history.length})</h3>\n        ${renderRecentHistory(n.data.history)}\n    `}